import{_ as l,l as n,o as e,c as i,v as r,p as s,x as o,d as p,i as c,S as h}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"Hasbrouck 信息份额","description":"","frontmatter":{"title":"Hasbrouck 信息份额","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/hasbrouck-is.md","filePath":"quant/hasbrouck-is.md","lastUpdated":1789023840000}'),u={name:"quant/hasbrouck-is.md"};function d(E,a,m,b,k,_){const t=n("Mermaid");return e(),i("div",null,[a[1]||(a[1]=r('<h1 id="hasbrouck-信息份额" tabindex="-1">Hasbrouck 信息份额 <a class="header-anchor" href="#hasbrouck-信息份额" aria-label="Permalink to &quot;Hasbrouck 信息份额&quot;">​</a></h1><div class="epigraph"><p>同一证券在多个市场上留下的报价，共享一个随机游走的有效价格；把这个游走的新息方差分解到各市场的扰动上，得到的就是各市场对价格发现的贡献。</p><footer>—— Hasbrouck, One Security, Many Markets: Determining the Contributions to Price Discovery, Journal of Finance, 1995</footer></div><p><a href="/quant/depth-mid">上一课</a>把多档可见量收成 \\(P(Q)\\)，最优档微价格是 \\(K=1\\) 的极限；小单看微价格，大单看沿簿均价。缺口从一张簿的读数转到多市场：同一索取权在若干交易所或现货/期货同时交易时，新信息先写进哪一个价格——这不是「谁更流动」或「价差更窄」。本课钉 Hasbrouck（1995）信息份额：协整系统里有效价格新息方差的分解。不重讲目标量 \\(Q\\)。对照 <a href="/quant/microstructure-noise">微观结构噪声</a> 的定价误差方差；后课流动性因子默认 IS 不是 PIN，也不是 Kyle \\(\\lambda\\)。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>深度加权给出一张簿上的 \\(P(Q)\\)，回答不了新信息先写进哪一个市场。若两个市场交易本质上同一索取权，长期看价格不能分道扬镳，否则存在套利。短期看，谁先动、谁跟随，噪声谁更大，可以完全不同。中间价、成交价都含微观结构噪声，简单比较「谁先跳一个 tick」会被弹跳欺骗。需要一个模型：每个市场的价格 = 共同有效价格 + 自身平稳误差，然后问：有效价格的新息，有多少方差来自市场 \\(i\\) 的扰动。</p><p>这个问题与「哪边成交量更大」不同。一个市场可以很活跃却主要在弹跳（份额低），另一个可以稀疏却常常先把有效价格挪走（份额高）。也与毒性不同：毒性问流动性提供者是否在亏，信息份额问发现发生在哪。把 IS 高的市场当成「更毒」没有理论依据。</p><h3 id="共同随机趋势与-vecm" tabindex="-1">共同随机趋势与 VECM <a class="header-anchor" href="#共同随机趋势与-vecm" aria-label="Permalink to &quot;共同随机趋势与 VECM&quot;">​</a></h3><p>记 \\(p_t\\) 为 \\(n\\) 个市场的价格向量。协整假定 \\(\\beta&#39;p_t\\) 平稳（通常取价差为平稳），而 \\(p_t\\) 本身 \\(I(1)\\)。向量误差修正模型为</p> \\[\\Delta p_t=\\alpha\\beta&#39;p_{t-1}+\\sum_{j=1}^{k}\\Gamma_j\\Delta p_{t-j}+\\varepsilon_t,\\qquad \\mathrm{Var}(\\varepsilon_t)=\\Omega. \\]<p>\\(\\alpha\\) 是误差修正速度：谁在价差出现后负责拉回去，谁就更像跟随者。Hasbrouck 把有效价格的新息写成 \\(\\varepsilon\\) 的线性组合，其方差为 \\(c\\Omega c&#39;\\) 一类二次型（\\(c\\) 来自共同趋势的载荷）。市场 \\(i\\) 的信息份额是：在 \\(\\Omega\\) 的某一种因子分解下，第 \\(i\\) 个正交新息对该方差的贡献占比。所有市场的 IS 之和为 1。</p><p><span class="marginnote">协整向量通常取 \\((1,-1)\\) 或对 ETF/期货做合约乘数调整。若两个价格根本不为同一索取权（不同到期、不同币种未对冲），强行估 IS 只是把不平稳的价差塞进误差修正，份额没有经济含义。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>采样时钟必须统一：Hasbrouck 原文用规则的短间隔（如一秒）取最后报价。更细的事件时间可以对齐到每一次任一市场的报价更新，未更新的市场沿用上一次——这会把慢市场写成一串零收益，份额自动偏向活跃市场，需要交代。滞后阶数用信息准则，但应稳定到份额对 \\(k\\) 不敏感。估计在每个交易日或滚动窗内做，避免隔夜跳空破坏协整。</p><p>\\(\\Omega\\) 不是对角的：市场新息瞬时相关，因为同一毫秒的信息或共同延迟。Cholesky 分解依赖变量次序：先放的市场会吃掉共有的瞬时方差，IS 被抬高。Hasbrouck 的做法是报告所有次序下的最小与最大 IS，把区间而不是一个点当成结果。市场很多时次序爆炸，可报上下界的均值，或改用后来的修正（如最大似然下的唯一分解），但原文的识别限度应写进表注。</p><h3 id="cholesky-次序与上下界" tabindex="-1">Cholesky 次序与上下界 <a class="header-anchor" href="#cholesky-次序与上下界" aria-label="Permalink to &quot;Cholesky 次序与上下界&quot;">​</a></h3><p>若 \\(\\Omega\\) 近乎对角，上下界收窄，份额稳健。若瞬时相关很高——两个做市商看同一公共信息、或数据时间戳精度不够——上下界会拉开到几乎 \\([0,1]\\)，这时 IS 不可用，应先改善时钟、或承认「发现发生在这一毫秒的公共信息里」，而不是硬拆给某一交易所。把某个市场永远放在 Cholesky 第一位再只报一个数字，是常见的美化。</p><p>Gonzalo–Granger 永久—暂时分解给出的是共同趋势的权重（谁的价格进入有效价格的水平），不依赖 \\(\\Omega\\) 的因子分解，因而没有次序问题；它回答的是「有效价格是各市场价格的哪种线性组合」，不是「新息方差从哪来」。两个指标可以分歧：一个市场噪声大但新息重要（IS 高、GG 权重低）。应同时报告，不要只选好看的那个。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是套利与学习。有效价值变动时，更快处理信息或更靠近知情流的市场先改报价；其他市场的做市商看到价差，用误差修正把报价拉回去。\\(\\alpha\\) 大的市场是跟随者；IS 高的市场是新息的主要来源。流动性好可以降低定价误差（1993 年的质量），但不自动提高 IS：它可以只是把别人已经发现的价格印得更勤。</p><p>与 Kyle、PIN 的接口：知情交易可以集中在某一市场，于是该市场 IS 高、同时 <a href="/quant/pin">PIN</a> 或毒性也可能高——这是可能的共现，不是定义。Kyle 的 \\(\\lambda\\) 描述该市场内部订单流如何冲击价格；IS 描述市场之间谁贡献有效价格方差。一个市场可以 \\(\\lambda\\) 很大（浅）但 IS 很高（信息先到这里），也可以相反。把 IS 当成流动性排序会把发现与深度混在一张表里。</p><h3 id="与-gonzalo–granger、pin-的差别" tabindex="-1">与 Gonzalo–Granger、PIN 的差别 <a class="header-anchor" href="#与-gonzalo–granger、pin-的差别" aria-label="Permalink to &quot;与 Gonzalo–Granger、PIN 的差别&quot;">​</a></h3><p>PIN 用单一市场的买卖计数估信息事件概率，没有「多市场贡献」。VPIN 是成交量时钟上的毒性代理。IS 不用方向计数，只用价格向量的协整。现货与期货之间估 IS，是价格发现文献的经典应用：到期临近、基差平稳时识别较好；远月合约与近月不是同一索取权，应先转换或只取近月。ETF 与篮子：篮子有构造延迟，IS 常偏向期货或活跃 ETF，但不意味着成分股「没有信息」，只意味着新息先出现在衍生品印记上。</p><p><span class="marginnote">时间戳精度是一等识别条件。把两个市场的时钟对不齐，领先滞后会被管道延迟写成「发现」。应使用交易所时间并处理夏令时、午休断开，而不是用本地接收时间。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>两个价格必须协整。结构断裂——一只腿停牌、最小报价单位调整、交易时段不一致——会让全日 VECM 无意义。多于两个市场时，IS 上下界变宽。把微价格、深度加权中间价与中点当成「三个市场」去估 IS，是把同一张簿的三种读数当成独立观测，共同噪声使分解无效。</p><p>高频下微观结构噪声占满 \\(\\Delta p\\)，协整关系被弹跳淹没，IS 会乱。Hasbrouck 自己使用的采样相对当时的数据已经是在噪声与信息之间折中；今天若用微秒，应先考虑是否应对价格做轻度平滑或改用中点。不要用 IS 去指导「把订单送到份额最高的市场」而不谈费用、延迟与可成交深度——发现贡献不是执行算法的充分统计。</p><p><span class="marginnote">信息份额不是市场份额，也不是成交量份额。报告时应并列成交量、价差与 IS 上下界，避免读者把「贡献了 70% 的发现」读成「70% 的量应该去那里」。</span></p>',27)),(e(),s(h,null,{default:o(()=>[c(t,{id:"mermaid-77",class:"mermaid",graph:"flowchart%20TD%0A%20%20P1%5B%22%E5%B8%82%E5%9C%BA%201%20%E4%BB%B7%E6%A0%BC%22%5D%20--%3E%20VECM%5B%22%E5%8D%8F%E6%95%B4%20VECM%22%5D%0A%20%20P2%5B%22%E5%B8%82%E5%9C%BA%202%20%E4%BB%B7%E6%A0%BC%22%5D%20--%3E%20VECM%0A%20%20VECM%20--%3E%20RW%5B%22%E5%85%B1%E5%90%8C%E6%9C%89%E6%95%88%E4%BB%B7%E6%A0%BC%E6%96%B0%E6%81%AF%22%5D%0A%20%20VECM%20--%3E%20A%5B%22%E8%AF%AF%E5%B7%AE%E4%BF%AE%E6%AD%A3%20%CE%B1%3A%20%E8%B0%81%E8%B7%9F%E9%9A%8F%22%5D%0A%20%20RW%20--%3E%20Chol%5B%22Cholesky%20%E6%AC%A1%E5%BA%8F%22%5D%0A%20%20Chol%20--%3E%20IS%5B%22%E5%90%84%E5%B8%82%E5%9C%BA%20IS%20%E4%B8%8A%E4%B8%8B%E7%95%8C%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Hasbrouck（1995）在多市场价格的协整系统里，把有效价格新息方差分给各市场，得到信息份额。</li><li>瞬时相关使 IS 依赖 Cholesky 次序，应报告上下界；时钟对齐是识别条件。</li><li>Gonzalo–Granger 给共同趋势权重，与 IS 互补，二者不必一致。</li><li>IS 不是流动性、不是 PIN、不是 Kyle \\(\\lambda\\)，也不应用同一张簿的多种读数去冒充多市场。</li><li>停牌、合约乘数、时段与噪声采样限制分解的可用性。</li><li>出处：Hasbrouck, <em>Journal of Finance</em>, 1995；定价误差与市场质量见 Hasbrouck, <em>Review of Financial Studies</em>, 1993。</li></ul>',2))])}const S=l(u,[["render",d]]);export{B as __pageData,S as default};
